def transform(grid):
    # Find separator: check if there's a column or row with all identical non-zero values
    rows_to_keep = None
    cols_to_keep = None

    for col in range(len(grid[0])):
        row0 = grid[0][col]
        if all(cell == row0 and cell != 0 for row in grid for cell in [row[col]]):
            cols_to_keep = col
            break

    for row in range(len(grid)):
        cell = grid[row][0]
        if all(cell == grid[i][row] and cell != 0 for i in range(len(grid))):
            rows_to_keep = row
            break

    if rows_to_keep is not None:
        result = [row[:rows_to_keep] for row in grid[:rows_to_keep+1]]
    elif cols_to_keep is not None:
        result = [[cell if cell != 0 else 0 for col_idx, cell in enumerate(row[:cols_to_keep])] for row in grid]
    else:
        result = grid

    # Transform pattern color to 2
    for i in range(len(result)):
        for j in range(len(result[i])):
            if result[i][j] != 0:
                result[i][j] = 2

    return result
